import sys
from typing import List, Tuple

def solve(n: int, m: int, subarrays: List[Tuple[int, int]]) -> Tuple[int, List[int]]:
    events = []
    for l, r in subarrays:
        events.append((l - 1, 1))
        events.append((r, -1))
    events.sort()

    count = 0
    mex = 0
    active_ranges = []
    for i, (pos, event_type) in enumerate(events):
        count += event_type
        if count > 0:
            active_ranges.append(pos)
        elif active_ranges:
            active_ranges.pop()

        if not active_ranges and i < len(events) - 1:
            next_pos = events[i + 1][0]
            while mex in active_ranges:
                mex += 1
            while mex < next_pos and mex in active_ranges:
                mex += 1

    array = [0] * n
    current = 0
    for i in range(n):
        if i == 0 or i > active_ranges[-1]:
            current = mex
        array[i] = current
        if i in active_ranges:
            active_ranges.remove(i)

    return mex, array

def main():
    n, m = map(int, input().split())
    subarrays = [tuple(map(int, input().split())) for _ in range(m)]
    result_mex, result_array = solve(n, m, subarrays)
    print(result_mex)
    print(*result_array)

if __name__ == "__main__":
    main()

